// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	openQueryPage,
	repositoryPageUrl,
	runQuery,
	serverBaseUrl,
	uniqueRepositoryId
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-design-system');

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: ['bsbm', 'spl'] });
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test('result headings show variable names exactly as written', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID);
	await runQuery(page, 'SELECT ?num1 ?x_y WHERE { BIND(1 AS ?num1) BIND(2 AS ?x_y) }');
	const headings = page.locator('#query-results table.data thead th');
	await expect(headings).toHaveCount(2);
	const rendered = await headings.evaluateAll((cells) => cells.map((cell) => ({
		text: cell.innerText.trim(),
		transform: getComputedStyle(cell).textTransform
	})));
	expect(rendered.map((cell) => cell.transform)).toEqual(['none', 'none']);
	// Written as in the query, with the question mark (plan task M4.3).
	expect(rendered.map((cell) => cell.text)).toEqual(['?num1', '?x_y']);
});

test('query page actions share one button height and one secondary border', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID);
	const metrics = await page.evaluate(() => ['#exec', '#explain-trigger', '#save-query-toggle', '#query-options-toggle']
		.map((selector) => {
			const element = document.querySelector(selector);
			const style = getComputedStyle(element);
			return { selector, height: element.getBoundingClientRect().height, border: style.borderTopColor };
		}));
	const heights = metrics.map((metric) => Math.round(metric.height));
	expect(new Set(heights).size, JSON.stringify(metrics)).toBe(1);
	const secondaryBorders = metrics.slice(1).map((metric) => metric.border);
	expect(new Set(secondaryBorders).size, JSON.stringify(metrics)).toBe(1);
});

/** Returns the first visible card (bordered, filled box) inside the page surface and the surface's width. */
async function firstCardGeometry(page) {
	return page.evaluate(() => {
		const surface = document.querySelector('#workbench-page-surface');
		const isCard = (element) => {
			const style = getComputedStyle(element);
			const rect = element.getBoundingClientRect();
			const filled = style.backgroundColor !== 'rgba(0, 0, 0, 0)' && style.backgroundColor !== 'transparent';
			return rect.width > 0 && rect.height > 0 && filled
				&& (parseFloat(style.borderTopWidth) > 0 || style.boxShadow !== 'none');
		};
		const candidates = Array.from(surface.querySelectorAll('*')).filter(isCard);
		const card = candidates[0];
		const rect = card.getBoundingClientRect();
		const surfaceRect = surface.getBoundingClientRect();
		return {
			card: card.tagName.toLowerCase() + (card.id ? '#' + card.id : '') + '.' + Array.from(card.classList).join('.'),
			left: rect.left, right: rect.right, width: rect.width, surfaceWidth: surfaceRect.width
		};
	});
}

test('browsing pages share one content width and form pages share one form width', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	const product1 = encodeURIComponent('<http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/instances/dataFromProducer1/Product1>');
	const browsing = ['summary', 'namespaces', 'types', 'query', 'explore?resource=' + product1];
	const rights = [];
	for (const view of browsing) {
		await page.goto(repositoryPageUrl(REPOSITORY_ID, view), { waitUntil: 'networkidle' });
		await page.locator('#workbench-page-surface').waitFor();
		rights.push({ view, ...(await firstCardGeometry(page)) });
	}
	const firstRight = rights[0].right;
	for (const geometry of rights) {
		expect(Math.abs(geometry.right - firstRight), JSON.stringify(rights)).toBeLessThanOrEqual(1);
	}
	// Export (redesigned on user request, 2026-10-01) puts its download card beside the preview, so the two
	// cards together take the browsing width.
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'export'), { waitUntil: 'networkidle' });
	const exportCards = await page.evaluate(() => {
		const surface = document.querySelector('#workbench-page-surface').getBoundingClientRect();
		const cards = Array.from(document.querySelectorAll('#workbench-page-surface .export-card'))
			.map((card) => card.getBoundingClientRect());
		return { surfaceLeft: surface.left, left: Math.min(...cards.map((card) => card.left)),
			right: Math.max(...cards.map((card) => card.right)), count: cards.length };
	});
	expect(exportCards.count, JSON.stringify(exportCards)).toBe(2);
	expect(Math.abs(exportCards.left - exportCards.surfaceLeft), JSON.stringify(exportCards)).toBeLessThanOrEqual(1);
	expect(Math.abs(exportCards.right - firstRight), JSON.stringify(exportCards)).toBeLessThanOrEqual(1);
	const forms = [`${REPOSITORY_ID}/add`, `${REPOSITORY_ID}/remove`, `${REPOSITORY_ID}/clear`,
		'NONE/create', 'NONE/delete', 'NONE/server'];
	for (const path of forms) {
		const [repositoryId, view] = path.split('/');
		await page.goto(repositoryPageUrl(repositoryId, view), { waitUntil: 'networkidle' });
		await page.locator('#workbench-page-surface').waitFor();
		const geometry = await firstCardGeometry(page);
		expect(Math.abs(geometry.width - Math.min(760, geometry.surfaceWidth)), path + ' ' + JSON.stringify(geometry))
			.toBeLessThanOrEqual(1);
	}
});

test('Remove and Clear stack labels above equally wide fields', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	for (const view of ['remove', 'clear']) {
		await page.goto(repositoryPageUrl(REPOSITORY_ID, view), { waitUntil: 'networkidle' });
		const form = page.locator(`#${view}-form`);
		await form.waitFor();
		const layout = await form.evaluate((element) => {
			const labels = Array.from(element.querySelectorAll('label[for]')).map((label) => {
				const control = document.getElementById(label.getAttribute('for'));
				return {
					for: label.getAttribute('for'),
					labelBottom: label.getBoundingClientRect().bottom,
					controlTop: control ? control.getBoundingClientRect().top : null
				};
			}).filter((entry) => entry.controlTop !== null);
			const widths = Array.from(element.querySelectorAll('input[type="text"], textarea'))
				.map((control) => Math.round(control.getBoundingClientRect().width));
			return { labels, widths };
		});
		expect(layout.labels.length, view).toBeGreaterThan(0);
		for (const entry of layout.labels) {
			expect(entry.labelBottom, `${view} ${entry.for}`).toBeLessThanOrEqual(entry.controlTop);
		}
		// Clear chooses its graph from one select (M6.4), so only Remove has text fields to compare.
		expect(layout.widths.length, `${view} ${JSON.stringify(layout.widths)}`).toBe(view === 'remove' ? 3 : 0);
		expect(new Set(layout.widths).size, `${view} ${JSON.stringify(layout.widths)}`).toBeLessThanOrEqual(1);
	}
});

test('editor overlay icons are drawn visibly as 28px ghost buttons', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID);
	const metrics = await page.evaluate(() => {
		const channel = (value) => {
			const normalized = value / 255;
			return normalized <= 0.03928 ? normalized / 12.92 : Math.pow((normalized + 0.055) / 1.055, 2.4);
		};
		const luminance = (rgb) => {
			const [r, g, b] = rgb.match(/\d+(\.\d+)?/g).slice(0, 3).map(Number);
			return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
		};
		return ['.yasqe_share', '.yasqe_fullscreenBtn'].map((selector) => {
			const button = document.querySelector(selector);
			const svg = button.querySelector('svg');
			const path = svg.querySelector('path');
			const pathStyle = getComputedStyle(path);
			const viewBox = svg.viewBox.baseVal;
			const scale = viewBox && viewBox.width ? svg.getBoundingClientRect().width / viewBox.width : 1;
			const effectiveStroke = parseFloat(pathStyle.strokeWidth)
				* (pathStyle.vectorEffect === 'non-scaling-stroke' ? 1 : scale);
			const background = getComputedStyle(document.querySelector('.CodeMirror')).backgroundColor;
			const foreground = pathStyle.stroke;
			const lighter = Math.max(luminance(foreground), luminance(background));
			const darker = Math.min(luminance(foreground), luminance(background));
			return {
				selector,
				size: Math.round(button.getBoundingClientRect().width),
				effectiveStroke,
				contrast: (lighter + 0.05) / (darker + 0.05)
			};
		});
	});
	for (const metric of metrics) {
		expect(metric.contrast, JSON.stringify(metric)).toBeGreaterThanOrEqual(3);
		expect(metric.effectiveStroke, JSON.stringify(metric)).toBeGreaterThanOrEqual(1);
		expect(metric.size, JSON.stringify(metric)).toBe(28);
	}
});
